insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 1, '1.7', array['1.7', '1.11']::text[], 'list_sequence', 'Rational end behavior: compare leading terms', 'End behavior of a rational function comes from the quotient of the leading terms, in three cases of which polynomial dominates.', '[{"label": "Numerator dominates", "meaning": "Quotient of leading terms is a nonconstant polynomial; the function has that polynomial''s end behavior, and a linear quotient gives a slant asymptote parallel to that line."}, {"label": "Neither dominates", "meaning": "Quotient of leading terms is a constant, which gives the horizontal asymptote."}, {"label": "Denominator dominates", "meaning": "Quotient is a constant over a nonconstant polynomial, giving a horizontal asymptote at y=0."}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u1-r1-031; ced=1.7.A.3, 1.7.A.4, 1.7.A.5')
